from __future__ import annotations

import json


def render_video_studio_page(service_url: str = "http://127.0.0.1:8765") -> str:
    """Render the UI shell only; all scene operations run in the isolated companion."""

    return _VIDEO_STUDIO_HTML.replace("__SERVICE_URL__", json.dumps(service_url))


_VIDEO_STUDIO_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>SBP Video Studio — UI Cockpit</title>
<style>
:root{color-scheme:dark;--bg:#040916;--panel:#0a1427;--panel2:#0d1b33;--line:#253b5d;--ink:#e7f3ff;--muted:#8ca5c2;--cyan:#55d9ff;--blue:#3578ff;--good:#45e39a;--warn:#ffc857;--bad:#ff637d}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 78% 0,#132c56 0,transparent 32%),linear-gradient(150deg,#030712,#071022 62%,#040816);color:var(--ink);font:14px/1.45 Inter,Segoe UI,Arial,sans-serif;min-height:100vh}
button,input,select,textarea{font:inherit}.shell{display:grid;grid-template-rows:auto 1fr auto;min-height:100vh}.topbar{display:flex;align-items:center;gap:8px;padding:10px 14px;background:rgba(5,11,24,.94);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:4;backdrop-filter:blur(16px)}
.brand{margin-right:12px}.brand strong{display:block;letter-spacing:.12em}.brand small{color:var(--cyan)}button,.button{border:1px solid var(--line);border-radius:7px;color:var(--ink);background:#12213a;padding:7px 11px;cursor:pointer;text-decoration:none}button:hover,.button:hover{border-color:var(--cyan);background:#172b4a}button.primary{background:linear-gradient(135deg,#1c64e7,#148ab0);border-color:#4fd6ff}button.danger{border-color:#7c3547}button:disabled{opacity:.45;cursor:not-allowed}.spacer{flex:1}.status-dot{width:9px;height:9px;border-radius:50%;background:var(--warn);box-shadow:0 0 12px currentColor}.status-dot.ok{background:var(--good)}
.main{display:grid;grid-template-columns:250px minmax(460px,1fr) 370px;gap:10px;padding:10px;min-height:0}.panel{background:linear-gradient(155deg,rgba(13,27,51,.95),rgba(7,15,31,.96));border:1px solid var(--line);border-radius:10px;min-height:0;overflow:hidden;box-shadow:0 18px 45px rgba(0,0,0,.2)}.panel h2,.panel h3{font-size:12px;text-transform:uppercase;letter-spacing:.12em;margin:0;color:#b8cae0}.panel-head{padding:10px 12px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.scroll{overflow:auto;max-height:calc(100vh - 160px);padding:10px}.project{padding:8px;border:1px solid transparent;border-radius:6px;cursor:pointer}.project:hover,.project.active{border-color:#31527c;background:#10223d}.project small{display:block;color:var(--muted)}.tree-group{margin:10px 0}.tree-group strong{display:block;color:var(--cyan);font-size:11px;text-transform:uppercase;margin-bottom:4px}.tree-item{padding:4px 7px;margin:2px 0;border-left:2px solid #345f91;background:rgba(12,29,53,.7);font-size:12px}
.stage{display:grid;grid-template-rows:minmax(330px,1fr) 170px;gap:10px;min-height:0}.preview{position:relative;background:radial-gradient(circle at 50% 45%,#142d58,#040813 66%);border:1px solid var(--line);border-radius:10px;overflow:hidden}.preview canvas{width:100%;height:100%;display:block}.preview-badge{position:absolute;top:12px;left:12px;padding:5px 8px;border:1px solid #2d527d;background:rgba(4,9,22,.8);border-radius:5px;color:var(--cyan);font-size:11px;letter-spacing:.08em}.preview-meta{position:absolute;right:12px;bottom:10px;color:var(--muted);font:11px ui-monospace,Consolas,monospace;text-align:right}.timeline{border:1px solid var(--line);border-radius:10px;background:rgba(6,14,28,.96);padding:10px;overflow:auto}.ruler{height:30px;position:relative;border-bottom:1px solid var(--line);margin-top:8px}.tick{position:absolute;top:0;height:100%;border-left:1px solid #375071;color:var(--muted);font-size:10px;padding-left:3px}.track{display:grid;grid-template-columns:130px 1fr;align-items:center;height:28px;border-bottom:1px solid rgba(37,59,93,.5);font-size:11px}.track-line{height:5px;background:#162b49;position:relative}.key{position:absolute;width:8px;height:8px;background:var(--cyan);transform:rotate(45deg);top:-2px}
.inspector textarea{width:100%;min-height:360px;resize:vertical;border:1px solid var(--line);border-radius:7px;background:#030916;color:#bfe8ff;padding:10px;font:11px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace}.field{margin-bottom:9px}.field label{display:block;color:var(--muted);font-size:11px;margin-bottom:3px}.field input,.field select{width:100%;padding:7px;border:1px solid var(--line);border-radius:6px;background:#071225;color:var(--ink)}.actions{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:8px 0}.layers{display:grid;gap:6px}.layer{padding:8px;text-align:left}.layer span{display:block;color:var(--muted);font-size:10px}.notice{min-height:46px;padding:10px 14px;border-top:1px solid var(--line);background:#050b17;color:var(--muted);font:12px ui-monospace,Consolas,monospace}.notice.good{color:var(--good)}.notice.bad{color:var(--bad)}.warning{padding:8px;border:1px solid #6b5528;background:#271e09;color:#ffd77e;border-radius:6px;font-size:11px;margin:8px 0}
dialog{width:min(760px,90vw);border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--ink);padding:0}dialog::backdrop{background:rgba(0,0,0,.7)}dialog header{padding:12px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}dialog main{padding:12px}dialog textarea{width:100%;height:250px;background:#030916;color:#c9e8ff;border:1px solid var(--line);padding:9px;font:12px ui-monospace,Consolas,monospace}
@media(max-width:1100px){.main{grid-template-columns:210px 1fr}.inspector{grid-column:1/3}.inspector .scroll{max-height:none}}@media(max-width:720px){.main{grid-template-columns:1fr}.panel,.inspector{grid-column:auto}.stage{min-height:620px}.topbar{flex-wrap:wrap}}
</style>
</head>
<body>
<div class="shell">
<header class="topbar">
  <a class="button" href="/dashboard">← UI Cockpit</a>
  <div class="brand"><strong>SBP VIDEO STUDIO</strong><small>General-purpose local scene construction</small></div>
  <button onclick="newProject()">New</button><button onclick="createSamples()">Samples</button><button onclick="validateScene()">Validate</button><button onclick="saveScene()">Save</button><button onclick="compileScene()">Compile</button><button class="primary" onclick="renderScene()">Render MP4</button>
  <label class="button">Import asset<input id="assetFile" type="file" hidden onchange="importAsset(this.files[0])"></label>
  <div class="spacer"></div><span id="serviceDot" class="status-dot"></span><span id="serviceLabel">Connecting…</span>
</header>
<main class="main">
  <section class="panel"><div class="panel-head"><h2>Projects & scene graph</h2><button onclick="refreshProjects()">↻</button></div><div class="scroll"><div id="projects"></div><hr style="border-color:var(--line);border-width:1px 0 0"><div id="sceneTree"></div></div></section>
  <section class="stage">
    <div class="preview"><canvas id="preview"></canvas><div class="preview-badge">DETERMINISTIC MANIFEST PREVIEW</div><div id="previewMeta" class="preview-meta"></div></div>
    <div class="timeline"><h3>Timeline / sequencer</h3><div id="ruler" class="ruler"></div><div id="tracks"></div></div>
  </section>
  <section class="panel inspector"><div class="panel-head"><h2>Scene inspector</h2><span id="dirtyLabel"></span></div><div class="scroll">
    <div class="actions"><button onclick="addItem('object')">+ Object</button><button onclick="addItem('material')">+ Material</button><button onclick="addItem('camera')">+ Camera</button><button onclick="addItem('light')">+ Light</button><button onclick="addItem('effect')">+ VFX</button><button onclick="addItem('overlay')">+ HUD/Text</button><button onclick="addItem('track')">+ Animation</button><button onclick="formatJson()">Format JSON</button></div>
    <div class="warning">Cockpit integration is read-only visualization. It cannot decide governance, authorize execution, or mutate canonical runtime state.</div>
    <h3 style="margin:12px 0 6px">Cockpit presentation layers</h3><div class="layers">
      <button class="layer" onclick="fromCockpit('rehearsal')">1 · Slower rehearsal / learning traversal<span>Assessors, operators, regulators, deployment enterprise</span></button>
      <button class="layer" onclick="fromCockpit('full-speed')">2 · Full-speed traversal<span>Recorded traversal at actual timing where available</span></button>
      <button class="layer" onclick="openScenario()">3 · Constructed scenario mode<span>Assessors, regulators, insurers and relevant parties</span></button>
    </div>
    <h3 style="margin:14px 0 6px">Canonical scene manifest</h3><textarea id="manifest" spellcheck="false"></textarea>
  </div></section>
</main>
<footer id="notice" class="notice">Starting local Video Studio companion…</footer>
</div>
<dialog id="scenarioDialog"><header><strong>Constructed scenario</strong><button onclick="scenarioDialog.close()">×</button></header><main><p>This remains hypothetical and non-authoritative.</p><textarea id="scenarioJson">{
  "title": "Constructed assessment scenario",
  "stages": [
    {"name": "Simulated deployment entry", "status": "hypothetical", "duration_seconds": 2},
    {"name": "Regulator review point", "status": "review", "duration_seconds": 2},
    {"name": "Insurer exposure review", "status": "review", "duration_seconds": 2}
  ]
}</textarea><div class="actions"><button class="primary" onclick="fromScenario()">Construct visualization</button><button onclick="scenarioDialog.close()">Cancel</button></div></main></dialog>
<script>
const SERVICE=__SERVICE_URL__;let scene=null,dirty=false;
const $=id=>document.getElementById(id);const notify=(message,kind='')=>{const n=$('notice');n.textContent=message;n.className='notice '+kind};
async function api(path,body){const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};const response=await fetch(SERVICE+path,options);let data;try{data=await response.json()}catch{throw new Error('Video Studio companion returned an unreadable response')}if(!response.ok||data.status==='ERROR')throw new Error(data.error||`${response.status} ${response.statusText}`);return data}
function readEditor(){let value;try{value=JSON.parse($('manifest').value)}catch(error){throw new Error('Manifest JSON: '+error.message)}return value}
function setScene(value,isDirty=false){scene=value;$('manifest').value=JSON.stringify(value,null,2);dirty=isDirty;$('dirtyLabel').textContent=dirty?'UNSAVED':'';draw();renderTree();renderTimeline()}
function changed(){try{scene=readEditor();dirty=true;$('dirtyLabel').textContent='UNSAVED';draw();renderTree();renderTimeline()}catch{} }$('manifest').addEventListener('input',changed);
async function connect(){try{const data=await api('/health');$('serviceDot').classList.add('ok');$('serviceLabel').textContent='Blender '+(data.tools.blender.available?'ready':'missing')+' · FFmpeg '+(data.tools.ffmpeg.available?'ready':'missing');notify('Workspace: '+data.workspace,'good');await refreshProjects();if(!scene)await newProject()}catch(error){$('serviceLabel').textContent='Companion offline';notify(error.message+' — launch Desktop V1 using the normal desktop launcher.','bad')}}
async function refreshProjects(){const data=await api('/projects');$('projects').innerHTML=data.projects.length?data.projects.map(p=>`<div class="project ${scene&&scene.project.id===p.id?'active':''}" onclick="loadProject('${p.id}')"><b>${escapeHtml(p.name)}</b><small>${p.duration_seconds}s · ${p.fps}fps · ${p.manifest_digest.slice(0,10)}</small></div>`).join(''):'<small>No saved projects yet.</small>'}
async function loadProject(id){const data=await api('/project?id='+encodeURIComponent(id));setScene(data.manifest);notify('Loaded '+data.manifest.project.name,'good');await refreshProjects()}
async function newProject(){const name='Untitled Scene';try{const data=await api('/new',{name});setScene(data.manifest);await refreshProjects();notify('Created '+data.manifest.project.name+'. Rename it in the manifest inspector when needed.','good')}catch(error){notify(error.message,'bad')}}
async function createSamples(){try{await api('/samples',{});await refreshProjects();notify('General, smoke, and three Cockpit-layer samples created.','good')}catch(error){notify(error.message,'bad')}}
async function validateScene(){try{const data=await api('/validate',{manifest:readEditor()});notify(data.status==='VALID'?'Manifest is deterministic and valid.':data.errors.join(' · '),data.status==='VALID'?'good':'bad')}catch(error){notify(error.message,'bad')}}
async function saveScene(){try{const data=await api('/save',{manifest:readEditor()});setScene(data.manifest);await refreshProjects();notify('Saved · '+data.manifest_digest,'good')}catch(error){notify(error.message,'bad')}}
async function compileScene(){try{notify('Compiling deterministic Blender render plan…');const data=await api('/compile',{manifest:readEditor()});notify('Compiled · '+data.plan.build_directory,'good')}catch(error){notify(error.message,'bad')}}
async function renderScene(){try{notify('Rendering locally with Blender and FFmpeg. This can take time…');const data=await api('/render',{manifest:readEditor()});const r=data.result,p=scene.project.id,d=r.manifest_digest.slice(0,16),f=scene.output.filename;const url=`${SERVICE}/artifact?project=${encodeURIComponent(p)}&digest=${d}&filename=${encodeURIComponent(f)}`;notify('Render complete · '+r.output_file,'good');window.open(url,'_blank')}catch(error){notify(error.message,'bad')}}
async function importAsset(file){if(!file)return;try{const b64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',',2)[1]);reader.onerror=reject;reader.readAsDataURL(file)});const data=await api('/asset-import',{filename:file.name,data_base64:b64,project_id:readEditor().project.id});setScene(data.manifest);notify('Imported '+file.name+' into the content-addressed cache.','good')}catch(error){notify(error.message,'bad')}finally{$('assetFile').value=''}}
async function runtimeSnapshot(){const response=await fetch('/desktop/latest',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Could not read the current Cockpit snapshot');return response.json()}
async function fromCockpit(layer,scenario){try{notify('Reading detached Cockpit observability snapshot…');const snapshot=await runtimeSnapshot();const data=await api('/cockpit',{snapshot,layer,scenario});setScene(data.manifest);await refreshProjects();notify('Created '+layer+' read-only visualization. Runtime state was not mutated.','good');scenarioDialog.close()}catch(error){notify(error.message,'bad')}}
function openScenario(){scenarioDialog.showModal()}function fromScenario(){try{return fromCockpit('constructed-scenario',JSON.parse($('scenarioJson').value))}catch(error){notify('Scenario JSON: '+error.message,'bad')}}
function addItem(kind){try{const d=readEditor(),stamp=Date.now().toString(36).slice(-6),id=kind+'-'+stamp;if(kind==='material')d.scene.materials.push({id,shader:{type:'principled',base_color:[0.05,0.35,0.9,1],metallic:0.3,roughness:0.35}});if(kind==='object')d.scene.objects.push({id,type:'primitive',primitive:'cube',material:d.scene.materials[0]?.id||null,transform:{location:[0,0,0],rotation:[0,0,0],scale:[1,1,1]}});if(kind==='camera'){d.scene.cameras.push({id,transform:{location:[4,-6,3],rotation:[65,0,35],scale:[1,1,1]},focal_length:50,target:null});d.scene.active_camera=id}if(kind==='light')d.scene.lights.push({id,type:'area',transform:{location:[0,-3,5],rotation:[25,0,0],scale:[1,1,1]},color:[0.7,0.85,1],energy:1000,size:5});if(kind==='effect')d.scene.effects.push({id,type:'particles',emitter:d.scene.objects[0]?.id||null,material:d.scene.materials[0]?.id||null,count:32,seed:1,start:0,end:Math.min(3,d.render.duration_seconds),lifetime:1.5,speed:0.5,spread:1,size:0.03});if(kind==='overlay')d.scene.overlays.push({id,type:'hud',content:'DATA / TITLE',position:[0.05,0.9],font_size:0.25,color:[0.3,0.85,1,1]});if(kind==='track'){const target=d.scene.objects[0]?.id;if(!target)throw new Error('Add an object before an animation track');d.timeline.tracks.push({id,target:'object:'+target,property:'rotation',keyframes:[{time:0,value:[0,0,0],interpolation:'LINEAR'},{time:d.render.duration_seconds,value:[0,0,360],interpolation:'LINEAR'}]})}setScene(d,true);notify('Added '+kind+'. Validate before rendering.')}catch(error){notify(error.message,'bad')}}
function formatJson(){try{setScene(readEditor(),true)}catch(error){notify(error.message,'bad')}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderTree(){if(!scene)return;const groups=[['Materials',scene.scene.materials],['Objects',scene.scene.objects],['Cameras',scene.scene.cameras],['Lights',scene.scene.lights],['Effects / VFX',scene.scene.effects],['HUD / data graphics',scene.scene.overlays],['Audio',scene.audio.tracks]];$('sceneTree').innerHTML=groups.map(([name,items])=>`<div class="tree-group"><strong>${name} (${items.length})</strong>${items.map(i=>`<div class="tree-item">${escapeHtml(i.id)} <small>${escapeHtml(i.type||i.asset_id||'')}</small></div>`).join('')}</div>`).join('')}
function renderTimeline(){if(!scene)return;const duration=Number(scene.render.duration_seconds)||1,r=$('ruler'),ticks=5;r.innerHTML=Array.from({length:ticks+1},(_,i)=>`<span class="tick" style="left:${i/ticks*100}%">${(duration*i/ticks).toFixed(1)}s</span>`).join('');$('tracks').innerHTML=scene.timeline.tracks.map(t=>`<div class="track"><span>${escapeHtml(t.id)}</span><div class="track-line">${t.keyframes.map(k=>`<i class="key" style="left:${Math.min(100,Number(k.time)/duration*100)}%"></i>`).join('')}</div></div>`).join('')||'<small>No animation tracks.</small>'}
function draw(){if(!scene)return;const canvas=$('preview'),box=canvas.getBoundingClientRect(),scale=devicePixelRatio||1;canvas.width=Math.max(1,box.width*scale);canvas.height=Math.max(1,box.height*scale);const c=canvas.getContext('2d');c.scale(scale,scale);const w=box.width,h=box.height;c.clearRect(0,0,w,h);c.strokeStyle='#16365e';for(let x=0;x<w;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=0;y<h;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}const objects=scene.scene.objects.filter(o=>o.type!=='empty').slice(0,40);objects.forEach((o,i)=>{const x=w/2+(Number(o.transform?.location?.[0])||0)*35,y=h/2-(Number(o.transform?.location?.[2])||0)*35+(Number(o.transform?.location?.[1])||0)*12,r=12+Math.min(25,Math.abs(Number(o.transform?.scale?.[0])||1)*7);c.fillStyle=o.type==='text'?'#55d9ff':`hsl(${205+i*19%110} 75% 55%)`;c.globalAlpha=.82;c.beginPath();o.primitive==='cube'?c.rect(x-r,y-r,r*2,r*2):c.arc(x,y,r,0,Math.PI*2);c.fill();c.globalAlpha=1;c.fillStyle='#d9efff';c.font='10px Segoe UI';c.fillText(o.id,x+r+4,y)});const m=scene.render;$('previewMeta').innerHTML=`${m.resolution.width} × ${m.resolution.height}<br>${m.fps} FPS · ${m.duration_seconds}s<br>${scene.scene.objects.length} objects · ${scene.scene.effects.length} effects`}
addEventListener('resize',draw);connect();
</script>
</body></html>'''
